DROP TABLE IF EXISTS `rating_attempts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rating_attempts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `rating_session_id` bigint unsigned NOT NULL,
  `student_id` bigint unsigned NOT NULL,
  `subject_id` bigint unsigned NOT NULL,
  `attempt_number` tinyint unsigned NOT NULL DEFAULT '1',
  `started_at` datetime DEFAULT NULL,
  `finished_at` datetime DEFAULT NULL,
  `correct_count` smallint unsigned NOT NULL DEFAULT '0',
  `total_questions` smallint unsigned NOT NULL DEFAULT '0',
  `percentage` decimal(5,2) DEFAULT NULL,
  `status` enum('in_progress','finished','auto_closed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_progress',
  `answers_json` json DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rating_attempts_subject_id_foreign` (`subject_id`),
  KEY `ra_main_idx` (`rating_session_id`,`student_id`,`subject_id`),
  KEY `rating_attempts_student_id_status_index` (`student_id`,`status`),
  CONSTRAINT `rating_attempts_rating_session_id_foreign` FOREIGN KEY (`rating_session_id`) REFERENCES `rating_sessions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `rating_attempts_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `rating_attempts_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
